  msg.statusCode = 500;
  msg.payload = { error: 'Server configuration error' };
  return [null, msg];
}
try {
  msg.user = jwt.verify(msg.token, secret);
  return [msg, null];
} catch (err) {
  msg.statusCode = 401;
  msg.payload = { error: 'Invalid or expired token' };
  return [null, msg];
}

